sqlGroup.select:
select a.*, (case when a.sex = '1' then '男' when a.sex ='2' then '女' else '其他' end) as sexName, (case when a.subscribe = '0' then '未关注' when a.subscribe = '1' then '已关注' else '未知' end) as subscribeName
from wx_member a
1 = 1
and a.wechatid = #{wechatid}
and a.openid = #{openid}
and a.unionid = #{unionid}
and a.nickname like '%${nickName}%'
order by a.id desc

sqlGroup.update:
update
	wx_member
set
	subscribe = #{subscribe}
where
	openid = #{openId}
